import Std
theorem target : ∀ n : Nat, n < 120 → (n ^ 2 + 7 * n + 3) % 97 ≠ 54 :=
begin
  intros n h,
  cases h with _ _;
  have D := 7^2 + 4 * 1 * 51;
  have D_mod : D % 97 = 59 := by decide;
  have not_square : ¬∃ x : Nat, x^2 % 97 = 59 := by decide;
  have not_soln : ¬∃ n : Nat, n^2 + 7 * n + 3 = 54 mod 97 := by decide;
  exact not_soln,
end

intros n h;
by contradiction;
assume h': (n^2 + n + 1) % 79 = 40;
have h'': n^2 + n + 1 ≡ 40 mod 79 := by rwa [modEq_iff_eq_mod] at h';
have h''': n^2 + n - 39 ≡ 0 mod 79 := by rw [h''];
let D : Nat := 1^2 - 4 * 1 * (-39) = 1 + 156 = 157;
have D_mod79 : D % 79 = -1 := by simp [D, modEq];
have D_not_quad_res : ¬∃x, x^2 ≡ -1 mod 79 :=
  by {
    have p : Nat := 79;
    have p_mod4 : p % 4 = 3 := by simp [p];
    have legendre : legendreSymbol (-1) p = -1 :=
      by {
        have p_odd : p % 2 = 1 := by simp [p];
        have legendre : legendreSymbol (-1) p = (-1) ^ ((p - 1) / 2) :=
          by rw [legendreSymbol_negOne, p_odd];
        have pow : (-1) ^ (39) = -1 := by simp [39];
        rfl
      };
    have not_quad_res : ¬∃x, x^2 ≡ -1 mod p :=
      by contradiction;
  };
contradiction

begin
  intro n,
  intro h1,
  intro h2,
  cases h2 with h2,
  have h3 : n < 60 := h1,
  have h4 : n ≥ 3 := h2,
  cases n,
  {
    -- n = 0, 1, 2
    have : false := by simp [h4],
    contradiction,
  },
  {
    -- n = 3
    have : 2^3 > 3^2 := by norm_num,
    contradiction,
  },
  {
    -- n = 4
    have : 2^4 > 4^2 := by norm_num,
    contradiction,
  },
  {
    -- n ≥ 5
    induction n with m h,
    {
      -- base case n = 5
      have : 2^5 > 5^2 := by norm_num,
    },
    {
      -- inductive step
      assume h_prev: 2^m > m^2,
      have : 2^(m+1) > (m+1)^2,
      {
        calc
          2^(m+1) = 2*2^m : by simp
          > 2*m^2 : by assumption
          ≥ m^2 + 2*m + 1 : by linarith
          > (m+1)^2 : by simp,
      },
    },
  },
end

begin
  intros n H1 H2,
  have H : 2^n > n^2 + 3 :=
    by cases n;
      { contradiction },
      { contradiction },
      {
        induction n with m h,
        {
          have : 2^5 > 5^2 +3 := by norm_num,
          exact this,
        },
        {
          have h : 2^m > m^2 +3 := h,
          have : 2^(m+1) > (m+1)^2 +3,
          {
            calc
              2^(m+1) = 2 * 2^m : by rw Nat.pow_succ
              > 2*(m^2 +3) : by rw h
              > (m+1)^2 +3 : 
                by norm_num at this; 
                calc
                  2*(m^2 +3) - ((m+1)^2 +3) = 2m^2 + 6 - (m^2 + 2m + 1 +3) = m^2 - 2m + 2
                  = (m - 1)^2 + 1 ≥ 16 : by norm_num
          },
          exact this,
        }
      },
  exact H,
end

by induction a
  intros b h
  case zero {
    simp [Nat.sub_zero, add_zero]
  }
  case succ a' {
    have h1: b ≤ a' → (a' - b) + b = a' := h
    have h2: b = a' + 1 → (a - b) + b = a :=
      by {
        simp [Nat.sub_eq_zero]
        ring
      }
    split
    case h1 {
      rw [Nat.sub_succ]
      simp [add_right]
    }
    case h2 {
      rw [Nat.sub_eq_zero]
      simp [add_right]
    }
  }

import Nat
theorem target : ∀ n : Nat, n < 120 → (2 * n ^ 3 + n) % 73 ≠ 38 :=
begin
  intros n h,
  have h1 : n < 73 ∨ 73 ≤ n ∧ n < 120 := by {cases h; exact Or.inl h},
  cases h1 with h2 h3,
  {
    have h4 : n < 73 := h2,
    have : (2 * n ^ 3 + n) % 73 ≠ 38 :=
      begin
        cases n;
        { rw [Nat.pow_zero, Nat.mul_zero, Nat.add_zero, Nat.mod_zero],
          show 0 ≠ 38,
        }
        { intros _, sorry }
      end,
    exact h4
  },
  {
    have h5 : n < 120 := h3.right,
    have h6 : (2 * n ^ 3 + n) % 73 = (2 * (n % 73) ^ 3 + (n % 73)) % 73 := by {cases h5; exact _},
    have h7 : (2 * (n % 73) ^ 3 + (n % 73)) % 73 ≠ 38 := by {cases h3.left; exact _},
    exact h7
  }
end

