begin
  intros n h1 h2,
  cases n with n h,
  { -- n = 0, 1, 2, 3
    exact false, -- 4 ≤ n is false
  },
  { -- n = 4
    exact false, -- 2^4 = 16 ≤ 4^2 + 17 = 33
  },
  { -- n = 5
    exact false, -- 2^5 = 32 ≤ 5^2 + 17 = 42
  },
  { -- n ≥ 6
    induction n with n h,
    { -- n = 6
      show 2 ^ 6 > 6 ^ 2 + 17,
      calc 64 > 36 + 17 : by simp
    },
    { -- n = k + 1 ≥ 7
      have h2 : 2 ^ (k + 1) > (k + 1) ^ 2 + 17,
        rw [pow_succ, pow_succ, pow_succ],
        calc 2 * 2 ^ k > 2 * (k ^ 2 + 17) : mul_lt_mul_right h2 (lt_add_right 0 17)
        ... > (k + 1) ^ 2 + 17 : by rw [pow_succ, pow_succ]; simp [mul_add, add_right_comm];
          calc 2 * (k ^ 2 + 17) = 2 * k ^ 2 + 34;
          (k + 1) ^ 2 + 17 = k ^ 2 + 2 * k + 1 + 17 = k ^ 2 + 2 * k + 18;
          2 * k ^ 2 + 34 > k ^ 2 + 2 * k + 18 ↔ k ^ 2 + 16 > 2 * k;
          k ^ 2 + 16 > 2 * k ↔ k ^ 2 - 2 * k + 16 > 0 ↔ (k - 1) ^ 2 + 15 > 0,
          by simp [add_right_inj, add_right_inj', add_comm, add_assoc],
      exact h2
    }
  }
end
